<style>
	.social-icon {
		display: flex;
		align-items: center;
		justify-content: center;
		border-radius: 50%; /* an optional background renders as a circle behind the icon */
		transition: opacity var(--motion-fast);
	}

	.social-icon svg {
		width: 1.5rem;
		height: 1.5rem;
	}

	.social-icon:hover {
		opacity: 0.7;
	}

	@media (min-width: 1024px) {
		.social-icon svg {
